function validate([source, target]) {
  if (typeof source !== 'string' || source.length < 1 || source.length > 1000) return 'source needs 1 to 1000 letters.';
  if (typeof target !== 'string' || target.length < 1 || target.length > 1000) return 'target needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(source) || !/^[a-z]+$/.test(target)) return 'Both strings may contain only lowercase English letters.';
  return null;
}

