function shortestWay(source, target) {
  let count = 0;
  let j = 0;
  while (j < target.length) {
    const start = j;
    for (let i = 0; i < source.length && j < target.length; i++) {
      if (source[i] === target[j]) {
        j++;
      }
    }
    if (j === start) {
      return -1;
    }
    count++;
  }
  return count;
}

