function shortestWay(source, target) {
  // best[k] = fewest subsequences that spell target's first k letters; try every next piece.
  const isSubsequence = (piece) => {
    let p = 0;
    for (const ch of source) if (p < piece.length && piece[p] === ch) p++;
    return p === piece.length;
  };
  const best = new Array(target.length + 1).fill(Infinity);
  best[0] = 0;
  for (let k = 0; k < target.length; k++) {
    if (best[k] === Infinity) continue;
    for (let end = k + 1; end <= target.length; end++)
      if (isSubsequence(target.slice(k, end))) best[end] = Math.min(best[end], best[k] + 1);
  }
  return best[target.length] === Infinity ? -1 : best[target.length];
}

