function generate(rand, size) {
  const word = (n, alphabet) => Array.from({ length: n }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('');
  if (size === 'large') {
    const source = word(20 + Math.floor(rand() * 981), 'abcdefghijklmnopqrstuvwxyz');
    // Draw target from source's own letters so that it can always be formed.
    return [source, word(1000, [...new Set(source)].join(''))];
  }
  const alphabet = 'abcd'.slice(0, 2 + Math.floor(rand() * 3));
  return [word(1 + Math.floor(rand() * 5), alphabet), word(1 + Math.floor(rand() * 8), alphabet)];
}
